import java.io.*;
import java.util.*;

public class TaskC {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        if (n >= 100) {
            out.print(0);
            return;
        }

        int[][] coords = new int[n + 1][5];
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < 5; j++) {
                coords[i][j] = in.nextInt();
            }
        }

        Set<Integer> badIndices = new HashSet<>();

        for (int i = 1; i <= n; i++) {
            boolean isBad = false;
            for (int j = 1; j <= n && !isBad; j++) {
                if (j == i) continue;
                for (int k = 1; k <= n && !isBad; k++) {
                    if (k == i || k == j) continue;

                    long[] v1 = new long[5];
                    long[] v2 = new long[5];
                    for (int d = 0; d < 5; d++) {
                        v1[d] = coords[j][d] - coords[i][d];
                        v2[d] = coords[k][d] - coords[i][d];
                    }

                    long dot = v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2] + v1[3] * v2[3] + v1[4] * v2[4];
                    long mag1Sq = v1[0]*v1[0] + v1[1]*v1[1] + v1[2]*v1[2] + v1[3]*v1[3] + v1[4]*v1[4];
                    long mag2Sq = v2[0]*v2[0] + v2[1]*v2[1] + v2[2]*v2[2] + v2[3]*v2[3] + v2[4]*v2[4];

                    if (mag1Sq == 0 || mag2Sq == 0) continue;

                    double cosTheta = (double) dot / Math.sqrt(mag1Sq * mag2Sq);
                    cosTheta = Math.min(1.0, Math.max(-1.0, cosTheta));
                    double angle = Math.toDegrees(Math.acos(cosTheta));

                    if (angle < 90.0 - 1e-9) {
                        isBad = true;
                    }
                }
            }
            if (isBad) badIndices.add(i);
        }

        out.println(n - badIndices.size());
        for (int i = 1; i <= n; i++) {
            if (!badIndices.contains(i)) {
                out.println(i);
            }
        }
    }
}
